        QCOMPARE(choice->property("displayText").toString(), QStringLiteral("A"));
        QCOMPARE(font->property("model").toStringList(), (QStringList{"Arial", "Comic Sans MS", "Impact", "Tahoma", "Verdana"}));
        choose(choice, 2);
        QCOMPARE(choice->property("displayText").toString(), QStringLiteral("A"));
