        QVERIFY(!find(top, QAccessible::TitleBar, QStringLiteral("Shift times")));
        QAccessibleInterface *timingOptions = find(top, QAccessible::Button, QStringLiteral("Shift times options"));
        QVERIFY(timingOptions);
