        QTRY_COMPARE(named("misspellRuleCount")->property("text").toString(), QStringLiteral("1 of 13 rules on"));
        QCOMPARE(named("misspellTabs")->property("currentIndex").toInt(), 0);
        click(named("misspellFindButton"));
