    QString writeTranslationFile(const char *name, bool tlMode = true)
    {
        const QString path = dir.filePath(QLatin1String(name));
        QFile f(path);
        if (!f.open(QIODevice::WriteOnly))
            return {};
        f.write(tlMode ? "[Script Info]\nScriptType: v4.00+\nTLMode: Yes\nTLMode Style: O\n\n[V4+ Styles]\n"
                       : "[Script Info]\nScriptType: v4.00+\n\n[V4+ Styles]\n");
        f.write("Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, "
                "Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, "
                "Alignment, MarginL, MarginR, MarginV, Encoding\n"
                "Style: Default,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,2,"
                "10,10,10,1\n"
                "Style: O,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,2,8,"
                "10,10,10,1\n\n[Events]\n"
                "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
                "Dialogue: 0,0:00:01.00,0:00:02.00,O,,0,0,0,\fD,Gate\n"
                "Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,Brama\n"
                "Dialogue: 0,0:00:03.00,0:00:04.00,O,,0,0,0,,Tower\n"
                "Dialogue: 0,0:00:03.00,0:00:04.00,Default,,0,0,0,,Wieza\n"
                "Dialogue: 0,0:00:05.00,0:00:06.00,O,,0,0,0,,{\\i1}Wall {\\b1}high\n"
                "Dialogue: 0,0:00:05.00,0:00:06.00,Default,,0,0,0,,\n");
        return path;
    }
    QPoint centreOf(QQuickItem *it) const
    {
        return it->mapToScene(QPointF(it->width() / 2, it->height() / 2)).toPoint();
    }
    bool inTheEditorView(QQuickItem *control)
    {
        auto *view = item("editorScroll");
        return view->mapRectToScene(view->boundingRect()).contains(control->mapRectToScene(control->boundingRect()));
    }
    void scrollTheEditorTo(QQuickItem *control)
    {
        static quint64 time = 0;
        auto *view = item("editorScroll");
        const QPoint over = view->mapToScene(QPointF(view->width() / 2, view->height() / 2)).toPoint();
        for (int notch = 0; notch < 20 && !QTest::qWaitFor([&] { return inTheEditorView(control); }, 300); ++notch) {
            const int up = control->mapToItem(view, QPointF(0, 0)).y() < 0 ? 1 : -1;
            QWheelEvent wheel(over, window->mapToGlobal(over), QPoint(), QPoint(0, 120 * up), Qt::NoButton,
                              Qt::NoModifier, Qt::NoScrollPhase, false);
            // Flickable takes the wheel scroll's speed from the event timestamps.
            wheel.setTimestamp(time += 1000);
            QCoreApplication::sendEvent(window, &wheel);
        }
        QVERIFY2(inTheEditorView(control), qPrintable(control->objectName()));
    }
    static QString q8(const std::u8string &s)
    {
        return QString::fromUtf8(reinterpret_cast<const char *>(s.data()), qsizetype(s.size()));
    }

    QObject *translationModeAction()
    {
        auto *menuItem = item<QObject>("translationModeMenuItem");
        return menuItem ? menuItem->property("action").value<QObject *>() : nullptr;
    }

    void translatorModeSwitchesWithOneStepEach()
    {
        auto *action = translationModeAction();
        QVERIFY(action);
        QVERIFY(!item<QObject>("translatorMode"));
        QVERIFY(!action->property("enabled").toBool());
        QVERIFY(application->openFile(writeTranslationFile("e5-switch.ass", false)));
        QTRY_VERIFY(action->property("enabled").toBool());
        auto *session = application->files().session(*application->workspace().editingTarget());
        QVERIFY(!action->property("checked").toBool());
        QVERIFY(!item("translationText")->isVisible());
        const auto *notConfirmed = item("originalNotConfirmed");
        QVERIFY(!notConfirmed || !notConfirmed->isVisible());
        const auto steps = session->historySize();
        QVERIFY(QMetaObject::invokeMethod(action, "trigger"));
        QTRY_VERIFY(application->editor().translationMode());
        QCOMPARE(session->historySize(), steps + 1);
        QCOMPARE(session->history().back().name, std::string("Turning on translator mode"));
        QCOMPARE(session->document().scriptInfo(u8"TLMode Style"), std::optional<std::u8string>(u8"TLmode"));
        QVERIFY(action->property("checked").toBool());
        QTRY_VERIFY(item("translationText")->isVisible());
        QTRY_VERIFY(item("originalNotConfirmed") && item("originalNotConfirmed")->isVisible());
        QVERIFY(item("originalMovingTags")->isVisible());

        auto *confirm = item<QObject>("translatorModeOffConfirm");
        QVERIFY(confirm);
        QVERIFY(QMetaObject::invokeMethod(action, "trigger"));
        QTRY_VERIFY(confirm->property("opened").toBool());
        QCOMPARE(confirm->property("text").toString(), QStringLiteral("Turn off Translation mode?"));
        QCOMPARE(confirm->property("defaultButton").value<QObject *>()->objectName(), QStringLiteral("messageBoxChoice_keepOn"));
        QVERIFY(action->property("checked").toBool());
        auto *confirmWindow = qobject_cast<QQuickWindow *>(confirm);
        const auto focused = [&] {
            auto *item = confirmWindow->activeFocusItem();
            return item ? item->objectName() : QString();
        };
        QTRY_COMPARE(focused(), QStringLiteral("messageBoxChoice_keepOn"));
        QTest::keyClick(confirmWindow, Qt::Key_Space);
        QTRY_VERIFY(!confirm->property("visible").toBool());
        QVERIFY(application->editor().translationMode());
        QCOMPARE(session->historySize(), steps + 1);
        QVERIFY(QMetaObject::invokeMethod(action, "trigger"));
        QTRY_VERIFY(confirm->property("opened").toBool());
        QVERIFY(QMetaObject::invokeMethod(confirm, "accept"));
        QTRY_VERIFY(!application->editor().translationMode());
        QCOMPARE(session->historySize(), steps + 2);
        QCOMPARE(session->history().back().name, std::string("Turning off translator mode"));
        QVERIFY(!action->property("checked").toBool());
        QTRY_VERIFY(!item("translationText")->isVisible());
        QVERIFY(application->editor().undo());
        QTRY_VERIFY(application->editor().translationMode());
        QVERIFY(action->property("checked").toBool());
        QVERIFY(application->editor().undo());
        QTRY_VERIFY(!application->editor().translationMode());
        QVERIFY(!action->property("checked").toBool());
    }

    void translatorModeIsForAssOnly()
    {
        const QString path = dir.filePath(QStringLiteral("e5.srt"));
        {
            QFile f(path);
            QVERIFY(f.open(QIODevice::WriteOnly));
            f.write("1\n00:00:01,000 --> 00:00:02,000\nA\n\n");
        }
        QVERIFY(application->openFile(path));
        QVERIFY(!translationModeAction()->property("enabled").toBool());
        QVERIFY(!application->turnOnTranslationMode());
    }

    void translatorModeNeedsScriptInfo()
    {
        const QString ass = dir.filePath(QStringLiteral("e5-sectionless.ass"));
        const QByteArray body = "[Events]\nFormat: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
                                "Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,A\n";
        {
            QFile f(ass);
            QVERIFY(f.open(QIODevice::WriteOnly));
            f.write(body);
        }
        QVERIFY(application->openFile(ass));
        // MUST KILL: processEvents flushes the tab's Qt.callLater external-change check before the save
        QCoreApplication::processEvents();
        auto *action = translationModeAction();
        auto *menuItem = item<QObject>("translationModeMenuItem");
        QTRY_VERIFY(action->property("enabled").toBool());
        QVERIFY(application->translationHint().isEmpty());
        QCOMPARE(menuItem->property("help").toString(),
                 QStringLiteral("Translator mode displays and saves both foreign text and translation text"));
        QVERIFY(QMetaObject::invokeMethod(action, "trigger"));
        QTRY_VERIFY(application->editor().translationMode());
        QVERIFY(action->property("checked").toBool());
        QVERIFY(application->editor().save());
        application->waitForWrites();
        QFile saved(ass);
        QVERIFY(saved.open(QIODevice::ReadOnly));
        const QByteArray bytes = saved.readAll();
        const QByteArray expected = QByteArray("[Script Info]\nTLMode: Yes\nActive Line: 0\n\n") + body + "\n[Hikari]\nLayout=";
        QCOMPARE(bytes.left(expected.size()), expected);
        QCOMPARE(bytes.count('\n'), expected.count('\n') + 1);
        QVERIFY(bytes.endsWith("\n"));

        const QString text = dir.filePath(QStringLiteral("e5-plain.txt"));
        {
            QFile f(text);
            QVERIFY(f.open(QIODevice::WriteOnly));
            f.write("first line\nsecond line\n");
        }
        application->addPage();
        QVERIFY(application->openFile(text));
        auto *session = targetSession();
        QCOMPARE(session->document().format(), core::SubtitleFormat::PlainText);
        QTRY_VERIFY(!action->property("enabled").toBool());
        QVERIFY(!application->translatorModeAvailable());
        QVERIFY(!application->turnOnTranslationMode());
        const QString hint = application->translationHint();
        QCOMPARE(hint, QStringLiteral("Translation needs an ASS file: plain text cannot store it."));
        QCOMPARE(menuItem->property("help").toString(), hint);
        QVERIFY(!application->canPasteTranslation());
        auto *grid = item("editingGrid");
        grid->forceActiveFocus();
        press(Qt::Key_Home);
        QTest::mouseClick(window, Qt::RightButton, Qt::NoModifier, grid->mapToScene(QPointF(grid->width() / 2, 30)).toPoint());
        auto *menu = grid->findChild<QObject *>(QStringLiteral("gridMenu"));
        QVERIFY(menu);
        QTRY_VERIFY(menu->property("visible").toBool());
        auto *paste = engine->rootObjects().first()->findChild<QObject *>(QStringLiteral("pasteTranslation"));
        QVERIFY(paste);
        QVERIFY(!paste->property("enabled").toBool());
        QCOMPARE(paste->property("help").toString(), hint);
        QVERIFY(QMetaObject::invokeMethod(menu, "close"));
        QVERIFY(!session->document().scriptInfo(u8"TLMode"));
    }

