        press(Qt::Key_Home);
        QTRY_COMPARE(application->editor().tagRuns().size(), 2);
        const auto placed = [&](int run) { return application->editor().tagRuns()[run - 1].toMap().value("placed").toBool(); };
        QVERIFY(application->editor().placeRun(1, 2, 3));
