    void editorShortcutsFollowTheLegacyDefaults()
    {
        const QString path = dir.filePath(QStringLiteral("keys.ass"));
        {
            QFile f(path);
            QVERIFY(f.open(QIODevice::WriteOnly));
            f.write("[Script Info]\nTLMode: Yes\nTLMode Style: O\n[Events]\n"
                    "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n"
                    "Dialogue: 0,0:00:01.00,0:00:02.00,O,,0,0,0,,one two\n"
                    "Dialogue: 0,0:00:01.00,0:00:02.00,Default,,0,0,0,,jeden\n"
                    "Dialogue: 0,0:00:03.00,0:00:04.00,O,,0,0,0,,three\n"
                    "Dialogue: 0,0:00:03.00,0:00:04.00,Default,,0,0,0,,\n");
        }
        application->editor().setShowTags(false);
        QVERIFY(application->openFile(path));
        auto &editor = application->editor();
        item("editingGrid")->forceActiveFocus();
        press(Qt::Key_Home);
        auto *original = item("lineText");
        QTRY_COMPARE(original->property("text").toString(), QStringLiteral("one two"));
        auto *session = application->files().session(*application->workspace().editingTarget());

        original->forceActiveFocus();
        original->setProperty("cursorPosition", 4);
        press(Qt::Key_Return, Qt::ShiftModifier);
        QCOMPARE(QString::fromUtf8(reinterpret_cast<const char *>(session->draftText()->c_str())),
                 QStringLiteral("one\\Ntwo"));
        QCOMPARE(original->property("text").toString(), QStringLiteral("one\ntwo"));

        press(Qt::Key_R, Qt::ControlModifier);
        QTRY_COMPARE(original->property("text").toString(), QStringLiteral("three"));
        press(Qt::Key_Down, Qt::AltModifier);
        QCOMPARE(session->document().lines()[1]->unconfirmed, true);
        QCOMPARE(session->document().lines().size(), 3u);
        press(Qt::Key_D, Qt::ControlModifier);
        QTRY_COMPARE(original->property("text").toString(), QStringLiteral("three"));
        QVERIFY(editor.problem().isEmpty());
    }

    void enterOnTheLastMicroDvdLineCountsFrames()
    {
        for (const bool withRate : {true, false}) {
            const QString path = dir.filePath(withRate ? QStringLiteral("rate.sub") : QStringLiteral("norate.sub"));
            {
                QFile f(path);
                QVERIFY(f.open(QIODevice::WriteOnly));
                f.write("{10}{20}abc|def\n{30}{40}x\n");
            }
            QVERIFY(application->openFile(path));
            auto *session = application->files().session(*application->workspace().editingTarget());
            if (withRate)
                QVERIFY(session->run(application::Command{"Set frame rate", session->revision(), {},
                                                          [](core::Document &d) {
                                                              d.setFrameRate(*core::FrameRate::make(24000, 1001));
                                                              return true;
                                                          }}));
            application->shell().refresh(&session->document(), nullptr);
            item("editingGrid")->forceActiveFocus();
            press(Qt::Key_End);
            auto *text = item("lineText");
            QTRY_COMPARE(text->property("text").toString(), QStringLiteral("x"));
            text->forceActiveFocus();
            press(Qt::Key_Return);
            QTRY_COMPARE(session->document().lines().size(), 3u);
            QVERIFY(application->editor().save());
            application->waitForWrites();
            QFile saved(path);
            QVERIFY(saved.open(QIODevice::ReadOnly));
            QCOMPARE(saved.readAll(), withRate ? QByteArray("{10}{20}abc|def\n{30}{40}x\n{40}{160}\n")
                                               : QByteArray("{10}{20}abc|def\n{30}{40}x\n{40}{}\n"));
            QVERIFY(application->closeEditingTarget());
        }
    }

    QQuickItem *settingsButton(const char *name) const { return dialogItem("settingsDialog", name); }
    void showSettingsPage(const char *id)
    {
        auto *pages = dialogItem("settingsDialog", "settingsPages");
        QVERIFY(pages);
        const auto list = settingsWindow()->property("pages").toList();
        for (qsizetype i = 0; i < list.size(); ++i)
            if (list[i].toMap().value(QStringLiteral("id")).toString() == QLatin1String(id)) {
                pages->setProperty("currentIndex", int(i));
                return;
            }
        QFAIL(id);
    }
    void answerSettingsQuestion(const char *choice)
    {
        QObject *box = nullptr;
        QTRY_VERIFY((box = settingsWindow()->property("question").value<QObject *>()) && box->property("visible").toBool());
        QVERIFY(QMetaObject::invokeMethod(box, "answer", Q_ARG(QVariant, QString::fromLatin1(choice))));
        QTRY_VERIFY(!box->property("visible").toBool());
    }
    QObject *openSettings()
    {
        auto *root = engine->rootObjects().first();
        auto *dialog = settingsWindow();
        auto *menuItem = root->findChild<QObject *>(QStringLiteral("settingsMenuItem"));
        if (!dialog || !menuItem || !QMetaObject::invokeMethod(menuItem->property("action").value<QObject *>(), "trigger"))
            return nullptr;
        return dialog;
    }
    QVariantMap settingsValues(QObject *dialog) const { return dialog->property("values").toMap(); }

    void settingsUpdatesPageKeepsTheUpdateOptions()
    {
        auto &updates = application->updates();
        const bool autoCheck = updates.autoCheck();
        updates.skipVersion(QStringLiteral("9.0.0"));
        auto *dialog = openSettings();
        QVERIFY(dialog);
        QTRY_VERIFY(dialog->property("visible").toBool());
        showSettingsPage("updates");
        QTRY_VERIFY(dialogItem("settingsDialog", "settingsPageUpdates")->isVisible());
        auto *check = dialogItem("settingsDialog", "setting_updater.autoCheck");
        QVERIFY(check);
        QCOMPARE(check->property("checked").toBool(), autoCheck);
        QCOMPARE(dialogItem("settingsDialog", "settingsSkippedVersion")->property("text").toString(), QStringLiteral("9.0.0"));
        QVERIFY(dialogItem("settingsDialog", "settingsInstallNote"));
        QVERIFY(QMetaObject::invokeMethod(check, "click"));
        QVERIFY(QMetaObject::invokeMethod(dialogItem("settingsDialog", "settingsOfferAgain"), "click"));
        QVERIFY(!dialogItem("settingsDialog", "settingsSkippedVersion")->isVisible());
        QCOMPARE(updates.autoCheck(), autoCheck);
        QCOMPARE(updates.skippedVersion(), QStringLiteral("9.0.0"));
        QVERIFY(QMetaObject::invokeMethod(settingsButton("settingsOk"), "click"));
        QTRY_VERIFY(!dialog->property("visible").toBool());
        QCOMPARE(updates.autoCheck(), !autoCheck);
        QVERIFY(updates.skippedVersion().isEmpty());
        QCOMPARE(application->settingsStore()->boolean("updater.autoCheck"), !autoCheck);
        updates.setAutoCheck(autoCheck);
    }

    void settingsPreviewSubtitlesAtFollowsTheFilter()
    {
        auto &settings = *application->settingsStore();
        auto restore = qScopeGuard([&] { settings.reset(QStringLiteral("video.previewSubtitlesAt")); });
        auto *dialog = openSettings();
        QVERIFY(dialog);
        QTRY_VERIFY(dialog->property("visible").toBool());
        showSettingsPage("video");
        auto *row = dialogItem("settingsDialog", "settingsPreviewSubtitlesAt");
        auto *choice = dialogItem("settingsDialog", "setting_video.previewSubtitlesAt");
        QVERIFY(row && choice);
        QTRY_VERIFY(choice->isVisible());
        QCOMPARE(choice->property("currentText").toString(), QStringLiteral("Video resolution (as encoded)"));
        QVERIFY(choice->isEnabled());
        dialog->setProperty("renderers", QStringList{QStringLiteral("libass"), QStringLiteral("vsfiltermod_textsub")});
        auto values = settingsValues(dialog);
        values.insert(QStringLiteral("video.subtitleProvider"), 1);
        dialog->setProperty("values", values);
        QTRY_VERIFY(!choice->isEnabled());
        QCOMPARE(row->property("note").toString(), QStringLiteral("Video resolution only with this filter."));
        values.insert(QStringLiteral("video.subtitleProvider"), 0);
        dialog->setProperty("values", values);
        QTRY_VERIFY(choice->isEnabled());
        QVERIFY(QMetaObject::invokeMethod(dialog, "reject"));
        QTRY_VERIFY(!dialog->property("visible").toBool());
        QVERIFY(!application->video().subtitlesAtScreenSize());
        settings.set("video.previewSubtitlesAt", 1);
        QVERIFY(application->video().subtitlesAtScreenSize());
        settings.reset(QStringLiteral("video.previewSubtitlesAt"));
        QVERIFY(!application->video().subtitlesAtScreenSize());
    }

